 5 | export const CameraParallax = ({ factor = 0.5 }) => {
 6 |   const { camera } = useThree();
 7 |   const mouse = useRef({ x: 0, y: 0, targetX: 0, targetY: 0 });
 8 | 
 9 |   useEffect(() => {
10 |     const handleMouseMove = (e) => {
11 |       mouse.current.targetX = (e.clientX / window.innerWidth - 0.5) * 2;
12 |       mouse.current.targetY = -(e.clientY / window.innerHeight - 0.5) * 2;
13 |     };
14 | 
15 |     window.addEventListener('mousemove', handleMouseMove);
16 |     return () => window.removeEventListener('mousemove', handleMouseMove);
17 |   }, []);
18 | 
19 |   useFrame((_, delta) => {
20 |     // Lerp mouse position for smooth fluid motion
21 |     mouse.current.x += (mouse.current.targetX - mouse.current.x) * delta * 2;
22 |     mouse.current.y += (mouse.current.targetY - mouse.current.y) * delta * 2;
23 | 
24 |     camera.position.x = mouse.current.x * factor * 1.5;
25 |     camera.position.y = mouse.current.y * factor * 1.0;
26 |     camera.lookAt(0, 0, -10);
27 |   });
28 | 
29 |   return null;
30 | };

